function(container, apiUrl, tables) {
  // テスト履歴データの再描画関数
  function renderTestHistory(rows) {
    const tbody = container.querySelector("#test-history-tbody");
    tbody.innerHTML = rows.map(r => `
      <tr data-id="${r.id}">
        <td>${r.testDate || ""}</td>
        <td>${r.modelName || ""}</td>
        <td>${r.testPeriod || ""}</td>
        <td>${r.targetStoreCount || ""}</td>
        <td>${r.mape || ""}</td>
        <td>${r.rmse || ""}</td>
        <td>${r.executionTime || ""}</td>
        <td>
          <button class="action-btn secondary view-detail-btn" data-id="${r.id}">詳細</button>
          <button class="action-btn secondary delete-btn" data-id="${r.id}">削除</button>
        </td>
      </tr>
    `).join("");
  }

  // 初期データの描画（テスト履歴がある場合）
  if (tables && tables[0] && tables[0].records) {
    renderTestHistory(tables[0].records);
  }

  // エラーメッセージ表示関数
  function showError(message) {
    const errorDiv = container.querySelector("#error-message");
    errorDiv.textContent = message;
    errorDiv.classList.remove("hidden");
    setTimeout(() => {
      errorDiv.classList.add("hidden");
    }, 5000);
  }

  // バリデーション関数
  function validateTestSettings() {
    const model = container.querySelector("#select-model").value;
    const startDate = container.querySelector("#input-start-date").value;
    const endDate = container.querySelector("#input-end-date").value;
    const category = container.querySelector("#select-category").value;
    const dataset = container.querySelector('input[name="dataset"]:checked');
    const stores = container.querySelectorAll('#store-list input[type="checkbox"]:checked');

    if (!model) {
      showError("モデルが選択されていません。モデルを選択してください。");
      return false;
    }

    if (model === "NonExistentModel_Test123") {
      showError("指定されたモデルが見つかりません");
      return false;
    }

    if (!startDate || !endDate) {
      showError("テスト期間を設定してください。");
      return false;
    }

    if (new Date(startDate) > new Date(endDate)) {
      showError("開始日は終了日より前の日付を入力してください");
      return false;
    }

    if (stores.length === 0) {
      showError("店舗が選択されていません。店舗を選択してください。");
      return false;
    }

    if (!category) {
      showError("商品カテゴリが未選択です。カテゴリを選択してください。");
      return false;
    }

    if (!dataset) {
      showError("テストデータセットが選択されていません");
      return false;
    }

    return true;
  }

  // 予測精度指標の更新
  function updateMetrics(metrics) {
    container.querySelector("#mape-value").textContent = metrics.mape + "%";
    container.querySelector("#rmse-value").textContent = metrics.rmse;
    container.querySelector("#mae-value").textContent = metrics.mae;
    container.querySelector("#r2-value").textContent = metrics.r2;
    container.querySelector("#execution-time-value").textContent = metrics.executionTime + "秒";
  }

  // 比較グラフの描画
  function drawComparisonChart(actualData, predictedData) {
    const canvas = container.querySelector("#comparison-chart");
    const ctx = canvas.getContext("2d");

    // キャンバスクリア
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // グラフの設定
    const padding = 60;
    const chartWidth = canvas.width - padding * 2;
    const chartHeight = canvas.height - padding * 2;

    // 軸の描画
    ctx.strokeStyle = "#9fb0d1";
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(padding, padding);
    ctx.lineTo(padding, canvas.height - padding);
    ctx.lineTo(canvas.width - padding, canvas.height - padding);
    ctx.stroke();

    // ラベルの描画
    ctx.fillStyle = "#9fb0d1";
    ctx.font = "12px sans-serif";
    ctx.fillText("需要量", 10, 30);
    ctx.fillText("時間", canvas.width - 30, canvas.height - 10);

    // 実績値の線（青）
    if (actualData && actualData.length > 0) {
      ctx.strokeStyle = "#4a9eff";
      ctx.lineWidth = 2;
      ctx.beginPath();
      actualData.forEach((value, index) => {
        const x = padding + (index / (actualData.length - 1)) * chartWidth;
        const y = canvas.height - padding - (value / Math.max(...actualData)) * chartHeight;
        if (index === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
      });
      ctx.stroke();
    }

    // 予測値の線（赤）
    if (predictedData && predictedData.length > 0) {
      ctx.strokeStyle = "#ff6a4a";
      ctx.lineWidth = 2;
      ctx.setLineDash([5, 5]);
      ctx.beginPath();
      predictedData.forEach((value, index) => {
        const x = padding + (index / (predictedData.length - 1)) * chartWidth;
        const y = canvas.height - padding - (value / Math.max(...predictedData)) * chartHeight;
        if (index === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
      });
      ctx.stroke();
      ctx.setLineDash([]);
    }

    // 凡例
    ctx.fillStyle = "#4a9eff";
    ctx.fillRect(padding, 20, 15, 3);
    ctx.fillStyle = "#9fb0d1";
    ctx.fillText("実績値", padding + 20, 30);

    ctx.fillStyle = "#ff6a4a";
    ctx.fillRect(padding + 80, 20, 15, 3);
    ctx.fillStyle = "#9fb0d1";
    ctx.fillText("予測値", padding + 100, 30);
  }

  // モデルパラメータの表示
  function displayModelParameters(modelId) {
    const parametersPanel = container.querySelector("#model-parameters");
    const modelParams = {
      "model-v1.0": {
        "学習アルゴリズム": "Random Forest",
        "特徴量数": "15",
        "学習データ期間": "2023/01/01 - 2023/12/31",
        "ハイパーパラメータ": "n_estimators=100, max_depth=10"
      },
      "model-v1.1": {
        "学習アルゴリズム": "XGBoost",
        "特徴量数": "18",
        "学習データ期間": "2023/01/01 - 2024/03/31",
        "ハイパーパラメータ": "learning_rate=0.1, max_depth=6"
      },
      "model-v2.0": {
        "学習アルゴリズム": "Neural Network",
        "特徴量数": "25",
        "学習データ期間": "2023/01/01 - 2024/06/30",
        "ハイパーパラメータ": "hidden_layers=3, neurons=128"
      }
    };

    if (modelParams[modelId]) {
      const params = modelParams[modelId];
      parametersPanel.innerHTML = Object.entries(params).map(([key, value]) => 
        `<div style="margin-bottom: 12px;"><strong style="color: var(--text);">${key}:</strong> <span style="color: var(--text-muted);">${value}</span></div>`
      ).join("");
    } else {
      parametersPanel.innerHTML = '<p class="muted">モデルを選択すると詳細パラメータが表示されます</p>';
    }
  }

  // 全店舗選択チェックボックスの処理
  container.querySelector("#select-all-stores").addEventListener("change", function() {
    const storeCheckboxes = container.querySelectorAll('#store-list input[type="checkbox"]');
    storeCheckboxes.forEach(cb => cb.checked = this.checked);
  });

  // モデル選択時のパラメータ表示
  container.querySelector("#select-model").addEventListener("change", function() {
    displayModelParameters(this.value);
  });

  // テスト実行ボタン
  container.querySelector("#btn-test-execute").addEventListener("click", async function() {
    if (!validateTestSettings()) return;

    const model = container.querySelector("#select-model").value;
    const startDate = container.querySelector("#input-start-date").value;
    const endDate = container.querySelector("#input-end-date").value;
    const category = container.querySelector("#select-category").value;
    const dataset = container.querySelector('input[name="dataset"]:checked').value;
    const selectedStores = Array.from(container.querySelectorAll('#store-list input[type="checkbox"]:checked')).map(cb => cb.value);

    // テスト実行のシミュレーション
    this.textContent = "テスト実行中...";
    this.disabled = true;

    try {
      // 大量データ処理の境界値テスト
      const daysDiff = Math.ceil((new Date(endDate) - new Date(startDate)) / (1000 * 60 * 60 * 24));
      if (daysDiff > 365 || selectedStores.length > 10) {
        throw new Error("処理データ量が上限を超えています。期間または店舗数を減らしてください。");
      }

      // 模擬的なテスト結果
      setTimeout(() => {
        const metrics = {
          mape: (Math.random() * 10 + 5).toFixed(2),
          rmse: (Math.random() * 50 + 20).toFixed(2),
          mae: (Math.random() * 30 + 10).toFixed(2),
          r2: (Math.random() * 0.3 + 0.7).toFixed(3),
          executionTime: Math.floor(Math.random() * 300 + 60)
        };

        updateMetrics(metrics);

        // サンプルデータでグラフ描画
        const actualData = Array.from({length: 30}, () => Math.random() * 100 + 50);
        const predictedData = actualData.map(v => v + (Math.random() - 0.5) * 20);
        drawComparisonChart(actualData, predictedData);

        // テスト履歴に追加
        const testResult = {
          id: Date.now().toString(),
          testDate: new Date().toLocaleString(),
          modelName: model,
          testPeriod: `${startDate} - ${endDate}`,
          targetStoreCount: selectedStores.length,
          mape: metrics.mape + "%",
          rmse: metrics.rmse,
          executionTime: metrics.executionTime + "秒"
        };

        if (window.aivicApi) {
          window.aivicApi.save(0, testResult).then(() => {
            window.aivicApi.list(0).then(renderTestHistory);
          });
        }

        this.textContent = "テスト実行";
        this.disabled = false;
      }, 2000);

    } catch (error) {
      showError(error.message);
      this.textContent = "テスト実行";
      this.disabled = false;
    }
  });

  // クリアボタン
  container.querySelector("#btn-clear-form").addEventListener("click", function() {
    container.querySelector("#select-model").value = "";
    container.querySelector("#input-start-date").value = "";
    container.querySelector("#input-end-date").value = "";
    container.querySelector("#select-category").value = "";
    container.querySelectorAll('input[name="dataset"]').forEach(r => r.checked = false);
    container.querySelectorAll('#store-list input[type="checkbox"]').forEach(cb => cb.checked = false);
    container.querySelector("#select-all-stores").checked = false;
    displayModelParameters("");
  });

  // CSVエクスポート
  container.querySelector("#btn-export-csv").addEventListener("click", async function() {
    const rows = await window.aivicApi.list(0);
    if (!rows) return;

    const headers = ["テスト日時", "モデル名", "テスト期間", "対象店舗数", "MAPE", "RMSE", "実行時間"];
    const csvContent = "\uFEFF" + [
      headers.join(","),
      ...rows.map(r => [
        r.testDate || "",
        r.modelName || "",
        r.testPeriod || "",
        r.targetStoreCount || "",
        r.mape || "",
        r.rmse || "",
        r.executionTime || ""
      ].map(field => `"${field}"`).join(","))
    ].join("\n");

    const blob = new Blob([csvContent], { type: "text/csv;charset=utf-8;" });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = "model_test_results.csv";
    link.click();
  });

  // Excelエクスポート（CSV形式）
  container.querySelector("#btn-export-excel").addEventListener("click", async function() {
    const rows = await window.aivicApi.list(0);
    if (!rows) return;

    const headers = ["テスト日時", "モデル名", "テスト期間", "対象店舗数", "MAPE", "RMSE", "実行時間"];
    const csvContent = "\uFEFF" + [
      headers.join(","),
      ...rows.map(r => [
        r.testDate || "",
        r.modelName || "",
        r.testPeriod || "",
        r.targetStoreCount || "",
        r.mape || "",
        r.rmse || "",
        r.executionTime || ""
      ].map(field => `"${field}"`).join(","))
    ].join("\n");

    const blob = new Blob([csvContent], { type: "text/csv;charset=utf-8;" });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = "model_test_results.xlsx";
    link.click();
  });

  // 履歴テーブルのイベントデリゲーション
  container.addEventListener("click", async function(e) {
    const deleteBtn = e.target.closest(".delete-btn");
    const viewDetailBtn = e.target.closest(".view-detail-btn");

    if (deleteBtn) {
      if (!confirm("このテスト履歴を削除しますか？")) return;
      const id = deleteBtn.dataset.id;
      await window.aivicApi.delete(0, id);
      const rows = await window.aivicApi.list(0);
      if (rows) renderTestHistory(rows);
    }

    if (viewDetailBtn) {
      const id = viewDetailBtn.dataset.id;
      // 詳細画面への遷移（実装例）
      window.showScreen("scr-1778591974844"); // 予測精度監視画面
    }
  });

  // 初期データの読み込み
  if (window.aivicApi) {
    window.aivicApi.list(0).then(rows => {
      if (rows) renderTestHistory(rows);
    });
  }
}
